            archive_rows += sizes.get(&pair.archive).copied().unwrap_or(0);
        }' \
  '        for grain in ds.grains() {
            live_rows += sizes
                .get(&crate::store::ddl::table_name(
                    &ds.name,
                    grain,
                    crate::store::ddl::TableKind::Live,
                ))
                .copied()
                .unwrap_or(0);
            archive_rows += sizes
                .get(&crate::store::ddl::table_name(
