run_mutation "sources/adapter: paths on a subscribed source warns" \
  crates/geode-core/src/source_config.rs \
  '                if !paths.is_empty() {' \
  '                if false {' \
  geode-core directory_keys_on_a_subscribed_source_warn_and_a_directory_source_still_needs_paths

